import reference_coherence as ref
P=B/'runtime/poursuite-20261020/microsocial/edition003';O=B/'runtime/poursuite-20261020/microsocial-option-coordination/edition001';O.mkdir(parents=True,exist_ok=False)
h=lambda v:hashlib.sha256(v if isinstance(v,bytes) else v.encode()).hexdigest();load=lambda p:json.loads(p.read_text());save=lambda n,x:(O/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
db=sqlite3.connect(f'file:{B}/corpus.sqlite?mode=ro',uri=True);db.row_factory=sqlite3.Row;db.execute('BEGIN')
