def capture(sid):
 a=dict(db.execute('SELECT * FROM articles WHERE code_id=? AND id=?',(code,sid)).fetchone());raw=db.execute("SELECT xml FROM documents WHERE code_id=? AND id=? AND kind='ARTICLE'",(code,sid)).fetchone()[0];raw=raw.decode() if isinstance(raw,bytes) else raw;prev=db.execute('SELECT * FROM drafts WHERE code_id=? AND source_id=?',(code,sid)).fetchone();sid=a.pop('id');body=a.pop('content_xml');r={**a,'source_id':sid,'source_xml':body,'source_notes_xml':source_notes(db,code,sid),'source_body_sha256':h(body),'source_notes_sha256':h(source_notes(db,code,sid)),'source_document_xml':raw,'source_document_sha256':h(raw),'previous_draft':dict(prev) if prev else None,'benefit_check_required':True,'impact_check_required':True,'source_url':'https://www.legifrance.gouv.fr/codes/article_lc/'+sid+'/'};return r
s=capture('LEGIARTI000043587337');assert s['previous_draft'] is None
refs=[capture('LEGIARTI000048683570'),capture('LEGIARTI000042684001')]
