r={'code_id':code,'source_id':s['source_id'],'source_sha256':s['source_sha256'],'number':s['number'],'status':'rewrite_draft','proposed_xml':body,'reason':'Coordonner le seul délai réglementaire de dénonciation du minimum volontaire avec le31décembre prévu par L613-7, afin que le règlement ne ferme pas cette faculté dès le31octobre.','review_notes':'Article source et note officielle lus en entier. La seule substitution du corps est31octobre→31décembre au deuxième alinéa du II ; I et III et les deux autres alinéas du II restent byte-identiques. La note du décret2021-300 prévoit l’application source au1janvier2023 et ne fixe pas le calendrier de cette réforme. L613-7 I permet la demande jusqu’au31décembre de l’année précédente et la dénonciation dans les mêmes conditions ; cette règle demeure dans le projet microsocial003 entier capturé séparément. Le report concerne la dénonciation pour l’année suivante, pas un changement rétroactif des années closes. Il ne crée ni nouveau délai de demande initiale, ni forclusion d’une création récente, ni formulaire ; la périodicité mensuelle/trimestrielle du I est inchangée. La déclaration des derniers revenus et l’échéancier du II restent régis par L613-2 et les règles de recouvrement applicables, sans rétablir de cotisations anciennes ou de taux supprimés. Coordination facultative à intégrer seulement après garde fraîche de L613-7 si son nouveau projet a été inscrit.','benefit_review':'Le minimum de cotisation reste une option expresse pour acquérir des droits, sans choix présumé ni minimum imposé. Sa dénonciation pour l’année suivante reste ouverte jusqu’au31décembre comme le prévoit la loi ; les demandes initiales, cas de création, reconduction tacite, choix trimestriel et droits déjà acquis sont conservés.','substantive_impact':{'version':1,'classification':'coordination_only','assessment':'Retirer une date réglementaire de renonciation plus précoce que le terme légal, sans modifier les taux ni compter une nouvelle baisse du forfait. La faculté volontaire devient cohérente entre les deux niveaux de normes.','scope_limitations':'Coordination bornée au II de R613-7. Elle ne prétend pas régler tous les délais des régimes indépendants, ni rouvrir les années closes, ni créer un remboursement automatique ou chiffrer un gain national.','new_burdens_review':'Aucune nouvelle formalité, donnée ou demande de remplacement. La voie de preuve de réception, le guichet de création, les flux entre caisses et les déclarations de liquidation existants sont maintenus ; seul le terme trop précoce est coordonné.','effects':[{'kind':'coordination','measure_id':'microsocial-minimum-option-deadline','description':'Aligner la dénonciation réglementaire du minimum volontaire sur le délai légal.','before':'Le II impose31octobre pour modifier la reconduction de l’option, alors que L613-7 prévoit31décembre et dénonciation dans les mêmes conditions.','after':'Le II retient31décembre ; aucun taux n’est modifié et la demande initiale reste gouvernée par L613-7.','unit':'other','affected_population':'Microentrepreneurs ayant choisi un minimum volontaire et souhaitant y renoncer pour l’année civile suivante.','conditions_and_transition':'Effets pour l’année suivante selon les mêmes règles annuelles ; aucune réouverture des exercices clos, aucun délai rétroactif ajouté. Les choix déjà exprimés et les droits acquis demeurent.','replacement_or_new_burdens':'Aucune procédure ou condition nouvelle ; ce seul alignement n’est pas compté comme baisse de cotisations supplémentaire.','source_quote':old,'proposed_quote':new}]}}
source=[s];ans=[r];validate_answer(ans,source)
save('source.json',source);save('answer.json',ans);save('dependencies.json',refs)
pending=next(x for x in load(P/'answer.json') if x['number']=='L613-7');save('pending-L613-7.json',{'edition':'microsocial/edition003','answer_file_sha256':h((P/'answer.json').read_bytes()),'article':pending,'body_sha256':h(pending['proposed_xml']),'role':'Proposition en attente distincte de la garde canonique. Les alinéas de demande/dénonciation sont inchangés entre source et projet ; recapturer les gardes si intégration entretemps.'})
snap=ref.capture(db,source,ans)
for d in refs:snap['targets'][ref.key(d)]=ref.view(db,ref.key(d))
save('reference-targets.json',snap);ref.check_guards(db,snap)
checks=[]
for x in source+refs:
 y=capture(x['source_id']);tests={k:y[k]==x[k] for k in ['source_sha256','source_xml','source_notes_xml','source_document_xml','previous_draft']};checks.append({'source_id':x['source_id'],'number':x['number'],'guards':tests,'all_match':all(tests.values())})
assert body.replace(new,old)==s['source_xml']
save('validation.json',{'read_transaction':'SQLite mode=ro BEGIN','guards':checks,'all_match':all(x['all_match'] for x in checks),'reference_guards_pass':True,'validate_answer_pass':True,'only_body_change':{'from':'31 octobre','to':'31 décembre','count':1},'all_other_body_bytes_identical':body.replace(new,old)==s['source_xml'],'source_body_sha256':h(s['source_xml']),'proposed_body_sha256':h(body),'canonical_mutation':False})
save('audit.json',{'scope':'Coordination favorable exacte, sans nouvelle baisse de taux','decision':'Proposer le seul remplacement31octobre par31décembre dans R613-7II, aucun autre corps modifié.','legal_basis':'L613-7I cinquième alinéa : demande31décembre de l’année précédente, dénonciation dans les mêmes conditions ; projet003 maintient ce paragraphe.','benefit':'La faculté de sortir du minimum volontaire n’est plus fermée avant le terme prévu par la loi ; elle concerne les futurs choix, sans réouverture des années closes.','not_new_rate_reduction':True,'new_obligations':[],'obligations_preserved':['Preuve de date de réception de la demande','Transmission via guichet unique en création','Déclaration des derniers revenus du régime minimum et échéancier','Transmission entre organismes pour les régimes concernés'],'source_note':'Entrée en vigueur source1janvier2023 ; ni3mois de création ni date ancienne artificiellement substitués.','integration_guard':'La garde canonique de L613-7 peut périmer lorsque microsocial003 sera intégré ; recapturer cette seule cible et relire son texte alors, pas accepter une garde devenue fausse.','source_ids':[s['source_id']]+[x['source_id'] for x in refs],'canonical_mutation':False})
for n in ['policy-coordinations.json','site-summaries.json']:(O/n).write_bytes((B/n).read_bytes())
save('manifest.json',{'frozen':True,'files':{p.name:h(p.read_bytes()) for p in O.iterdir() if p.is_file() and p.name!='manifest.json'},'canonical_mutation':False})
